\label{def:bspde-solution}
Let $\theta\le\tau_k$ be an $\mathbb F^Y$-stopping time and
let $\gamma\in\mathscr G_\theta^{n_*+1}$.
We call a pair $(f,g)$ a weighted Sobolev solution
of the BSPDE \eqref{eq:intro-dual-bspde} if, for some $\ell>0$,
the field $f$ is $\mathbb F^Y$-adapted, $g$ is
$\mathbb F^Y$-predictable, $f\in L^\infty(\Omega\times[0,\theta]\times\mathbb R^d)$ and
\begin{align}
\mathbb E^\mathbb Q\left[
	\operatorname*{ess\,sup}_{0\le s\le\theta}\left\lVert f_s\right\rVert_{H_\ell^{n_*}}^2
	+\int_0^\theta
	\left\lVert g_s\right\rVert_{H_\ell^{n_*}(\mathbb R^d;\mathbb R^m)}^2\,\,\mathrm d s
	\right]<\infty.
	\label{eq:solution-norm}
\end{align}
Moreover, for every $\varphi\in C_c^\infty(\mathbb R^d)$
and $t\in[0,T]$, the identity
\begin{align}
	\left\langle f_{t\wedge\theta},\varphi\right\rangle
	={}&\left\langle \gamma,\varphi\right\rangle
	+\int_{t\wedge\theta}^{\theta}
	\left\langle f_s,L_s^*\varphi\right\rangle\,\,\mathrm d s
	\notag\\
	&+\int_{t\wedge\theta}^{\theta}
	\left\langle h(\cdot,u_s)^\top g_s,\varphi\right\rangle\,\,\mathrm d s
	-\int_{t\wedge\theta}^{\theta}
	\left\langle g_s,\varphi\right\rangle^\top\,\,\mathrm d Y_s
	\label{eq:weak-bspde}
\end{align}
holds $\mathbb Q$-a.s..

\label{thm:main-bspde}
	Suppose Assumptions \ref{ass:filtering} and
	\ref{ass:bspde-regularity} hold.
	Fix $k\in\mathbb N$, an $\mathbb F^Y$-stopping time
	$\theta\le\tau_k$, and $\gamma\in\mathscr G_\theta^{n_*+1}$.
	Then \eqref{eq:intro-dual-bspde} admits a unique
	weighted Sobolev solution $(f,g)$ with bounded first
	component, satisfying \eqref{eq:solution-norm}
	with $\ell=d/2+2$.
	Moreover, $f$ admits a jointly measurable version that is
	$\mathbb Q$-almost surely continuous in $(t,x)$ on
	$[0,\theta]\times\mathbb R^d$.
	For every $\lambda\ge d/2+2$ and every multi-index
	$\alpha$ with $|\alpha|\le2$, the solution satisfies
	\begin{align}
		\mathbb E^\mathbb Q\Bigg[
		&\operatorname*{ess\,sup}_{0\le s\le\theta}\sup_{x\in\mathbb R^d}
		\frac{|D^\alpha f_s(x)|^2}{\left\langle x\right\rangle^{2\lambda}}
		+\int_0^\theta\sup_{x\in\mathbb R^d}
		\frac{|D^\alpha g_s(x)|^2}{\left\langle x\right\rangle^{2\lambda}}\,\mathrm d s
		\Bigg]<\infty.
		\label{eq:weighted-sup-2}
	\end{align}

\label{lem:flow-estimates}
	Under Assumptions \ref{ass:filtering} and \ref{ass:bspde-regularity}.
	Let $\widetilde{\mathbb Q}$ be any probability measure equivalent to $\mathbb Q$
	under which $W$ remains an $\mathbb F$-Brownian motion.
	For every $2\le q<\infty$ and $j=1,\ldots,n_*$,
	\begin{align}
		\mathbb E^{\widetilde{\mathbb Q}}
		\sup_{t\le s\le T}|\Phi_{t,s}(x)|^q
		&\le C_{k,q}\left\langle x\right\rangle^q,
		\label{eq:flow-state-moment}\\
		\sup_{0\le t\le T}\sup_{x\in\mathbb R^d}
		\mathbb E^{\widetilde{\mathbb Q}}
		\sup_{t\le s\le T}|D_x^j\Phi_{t,s}(x)|^q
		&\le C_{j,q}.
		\label{eq:flow-derivative-moment}
	\end{align}
	Moreover,
	\begin{align}
		\sup_{0\le t\le T}\sup_{x\in\mathbb R^d}
		\mathbb E^{\widetilde{\mathbb Q}}\sup_{t\le s\le T}
		\Bigg[
		&J_{t,s}(x)^q+J_{t,s}(x)^{-q}
		+\sum_{j=1}^{n_*}
		\big|(D^j\Psi_{t,s})(\Phi_{t,s}(x))\big|^q
		\Bigg]
		\le C_{k,q}.
		\label{eq:maximal-inverse-flow-moments}
	\end{align}

\label{prop:param-likelihood}
For every $(t,x)\in[0,T]\times\mathbb R^d$, $Z^{t,x}$ is a uniformly
integrable $\mathbb Q$-martingale on $[0,T]$. Consequently,
\begin{equation}
	\frac{\,\mathrm d\widehat\mathbb Q^{t,x}}{\,\mathrm d\mathbb Q}\bigg|_{\mathcal F_T}
	=Z_T^{t,x}=Z_\theta^{t,x}
	\label{eq:Qhat-tx}
\end{equation}
defines an equivalent probability measure.
Under $\widehat\mathbb Q^{t,x}$, $W$ and the process
\begin{equation}
	\widehat Y_s^{t,x}
	:=Y_s-\int_0^s\mathbf 1_{\{t<a\le\theta\}}
	h(X_a^{t,x},u_a)\,\mathrm d a,
	\qquad 0\le s\le T,
	\label{eq:Yhat-tx}
\end{equation}
are independent $\mathbb F$-Brownian motions.

\label{lem:conditional-flow-polynomial}
Let $\widetilde\mathbb Q$ be any probability measure equivalent to $\mathbb Q$ under which
$W$ remains Brownian.  Fix $j\le n_*$ and $2 \leq q<\infty$.  There is a
deterministic polynomial $P_{j,q}$ with nonnegative coefficients such that,
for every stopping time $\rho$ with $t\le\rho\le T$,
\begin{equation}
 \mathbb E^{\widetilde\mathbb Q}\left[
   \sup_{\rho\le s\le T}
   \sum_{i=1}^j|D_x^iX_s^{t,x}|^q
   \middle|\mathcal F_\rho\right]
 \le P_{j,q}\left(1+\sum_{i=1}^j|D_x^iX_\rho^{t,x}|\right).
 \label{eq:conditional-flow-polynomial}
\end{equation}
The degree and coefficients of $P_{j,q}$ depend only on the positive-order
derivative bounds, $j,q,$ and $T$.

\label{prop:uniform-parameter}
	For every $2\le q<\infty$ and every multi-index $\beta$ with
	$|\beta|\le n_*$, the solution of \eqref{eq:truncated-BSDE} satisfies
	\begin{align}
		\mathbb E^\mathbb Q\sup_{t\le s\le T}|D_x^\beta F_s^{N,t,x}|^q
		&\le C_{k,\beta,q},
		\label{eq:uniform-F-parameter}\\
		\mathbb E^\mathbb Q\left(\int_t^T
		\bigl(|D_x^\beta G_s^{N,t,x}|^2
		+|D_x^\beta\widetilde G_s^{N,t,x}|^2\bigr)\,\mathrm d s
		\right)^{q/2}
		&\le C_{k,\beta,q}\left\langle x\right\rangle^{q},
		\label{eq:uniform-G-parameter}
	\end{align}
	where $C_{k,\beta,q}$ is independent of $N,t,x$.

\label{prop:density-stability}
For every deterministic $(t,x)$, \eqref{eq:untruncated-BSDE} has a unique
solution with bounded first component and square-integrable martingale
integrands.  Moreover, as $N\to\infty$,
\begin{align}
	F^{N,t,x}
	&\longrightarrow F^{t,x}
	&&\text{in }\mathbb S^2,
	\label{eq:F-strong}\\
	(G^{N,t,x},\widetilde G^{N,t,x})
	&\longrightarrow(G^{t,x},\widetilde G^{t,x})
	&&\text{in }
	\mathbb H^2(\mathbb R^m)\times\mathbb H^2(\mathbb R^r).
	\label{eq:G-strong}
\end{align}

In addition, at time $t=0$,  for every $R<\infty$,   the following hold 
\begin{align}
	\int_{B_R}\mathbb E^\mathbb Q\sup_{0\le s\le T}
	|F_s^{N,0,x}-F_s^{0,x}|^2\,\mathrm d x
	&\longrightarrow0,
	\label{eq:local-parameter-F0}\\
	\int_{B_R}\mathbb E^\mathbb Q\int_0^T
	|G_s^{N,0,x}-G_s^{0,x}|^2\,\mathrm d s\,\mathrm d x
	&\longrightarrow0.
	\label{eq:local-parameter-G0}
\end{align}
The limiting fields $F^{0,\cdot}$ and $G^{0,\cdot}$ admit jointly
measurable versions in $(\omega,s,x)$.

\label{lem:weighted-multiplier}
For $y\in\mathbb R^d$ and $0\le s\le\theta$, let $P_s(y)$ be any fixed
polynomial, with deterministic coefficients, in the components of
\[
\bigl\{D^j\Phi_s(y),\,
D^j\Psi_s(\Phi_s(y)):1\le j\le n_*\bigr\}
\quad
J_s(y),\;\text{and} \; \; J_s(y)^{-1}.
\]
Then, for every $m>0$ and every finite $q\ge1$,
\begin{equation}
 \left\|
   \sup_{0\le s\le\theta}
   \left\langle \Phi_s(y)\right\rangle^{-m}J_s(y)|P_s(y)|
 \right\|_{L^q(\mathbb Q)}
 \le C_{m,q,k,P}\left\langle y\right\rangle^{-m}.
 \label{eq:weighted-multiplier}
\end{equation}

\label{prop:diagonal-Y}
For each $N$, choose and fix a jointly measurable version of $f^N_s(x)$
defined by \eqref{eq:reconstruct-N}, whose sample paths are 
continuous in $(s,x)$.  Then, for every deterministic
$s\in[0,T]$ and $x\in\mathbb R^d$,
\begin{equation}
	f_{s\wedge\theta}^N(x)
	=
	\mathbf 1_{\{s\le\theta\}}F_s^{N,s,x}
	+\mathbf 1_{\{s>\theta\}}\gamma(x),
	\qquad \mathbb Q\text{-a.s.}
	\label{eq:diagonal-Y}
\end{equation}
For this fixed version, the stopped process
$f^N_{\cdot\wedge\theta}$ is a $\mathbb G^k$-adapted
$C(\mathbb R^d)$-valued process, where $C(\mathbb R^d)$ is equipped
with the topology of uniform convergence on compact sets.

\label{prop:local-eulerian}

	For every $R<\infty$,
	\begin{align}
		\mathbb E^\mathbb Q\sup_{0\le s\le\theta}
		\int_{B_R}|f_s^N(x)-f_s(x)|^2\,\mathrm{d}x
		&\longrightarrow0,
		\label{eq:local-f-strong}\\
		\mathbb E^\mathbb Q\int_0^\theta\int_{B_R}
		|g_s^N(x)-g_s(x)|^2\,\mathrm{d}x\,\mathrm{d}s
		&\longrightarrow0.
		\label{eq:local-g-strong}
	\end{align}
	Moreover, the  process
	$
	\bigl(f_{s\wedge\theta}|_{B_R}\bigr)_{0\le s\le T}
	$
	is $\mathbb G^k$-adapted with values in $L^2(B_R)$.

Define 
\[
 \mathcal A_N(y):=\int_0^\theta
 |G_s^{N,0,y}-G_s^{0,y}|^2\,\mathrm d s,
 \qquad
 \mathcal B_N(y):=\sup_{s\le\theta}
 |F_s^{N,0,y}-F_s^{0,y}|^2.
\]
By Proposition \ref{prop:density-stability}, for every $K<\infty$,
\begin{align}
 \|\mathcal A_N\|_{L^1(\mathbb Q\otimes\,\mathrm d y;B_K)}
 +\|\mathcal B_N\|_{L^1(\mathbb Q\otimes\,\mathrm d y;B_K)}\longrightarrow0.
 \label{eq:eulerian-controls-L1}
\end{align}
For $r>1$, \eqref{eq:uniform-F-parameter}-\eqref{eq:uniform-G-parameter} and Fatou's lemma give
\begin{align}
 \sup_N\left(
 \|\mathcal A_N\|_{L^r(\mathbb Q\otimes\,\mathrm d y;B_K)}
 +\|\mathcal B_N\|_{L^r(\mathbb Q\otimes\,\mathrm d y;B_K)}
 \right)<\infty.
 \label{eq:eulerian-controls-high}
\end{align}
Thus, for $1<p<r$, we have 
\begin{align}
 \|\mathcal A_N\|_{L^p(\mathbb Q\otimes\,\mathrm d y;B_K)}
 +\|\mathcal B_N\|_{L^p(\mathbb Q\otimes\,\mathrm d y;B_K)}
 \longrightarrow0.
 \label{eq:eulerian-controls-interpolated}
\end{align}

Let  $J^*(y):=\sup_{s\le\theta}J_s(y)$.   H\"older's inequality and
\eqref{eq:maximal-inverse-flow-moments} imply that 
\begin{align}
 \int_{B_K}\mathbb E^\mathbb Q\int_0^\theta
 |G_s^{N,0,y}-G_s^{0,y}|^2J_s(y)\,\mathrm d s\,\mathrm d y
 &\longrightarrow0,
 \label{eq:eulerian-G-core}\\
 \mathbb E^\mathbb Q\int_{B_K}\mathcal B_N(y)J^*(y)\,\mathrm d y
 &\longrightarrow0.
 \label{eq:eulerian-F-core}
\end{align}

Changing variables $x=\Phi_s(y)$, we have 
\begin{align*}
 &\mathbb E^\mathbb Q\int_0^\theta\int_{B_R}|g_s^N(x)-g_s(x)|^2\,\mathrm d x\,\mathrm d s\\
 &\quad=\int_{\mathbb R^d}\mathbb E^\mathbb Q\int_0^\theta
 |G_s^{N,0,y}-G_s^{0,y}|^2J_s(y)
 \mathbf 1_{\{|\Phi_s(y)|\le R\}}\,\mathrm d s\,\mathrm d y.
\end{align*}
For $a>d+2$, applying Lemma \ref{lem:weighted-multiplier},
\eqref{eq:uniform-G-parameter}, and
$\mathbf 1_{\{|\Phi_s(y)|\le R\}}\le C_{R,a}\left\langle \Phi_s(y)\right\rangle^{-a}$, we have 
\begin{align}
 \mathbb E^\mathbb Q\int_0^\theta
 |G_s^{N,0,y}-G_s^{0,y}|^2J_s(y)
 \mathbf 1_{\{|\Phi_s(y)|\le R\}}\,\mathrm d s
 \le C_R\left\langle y\right\rangle^{2-a},
 \label{eq:explicit-eulerian-tail}
\end{align}
uniformly in $N$.  Since $\left\langle y\right\rangle^{2-a}\in L^1(\mathbb R^d)$, splitting the
$y$-integral into $B_K$ and $B_K^c$, then using
\eqref{eq:eulerian-G-core}, proves \eqref{eq:local-g-strong}.

Similarly,
\begin{align*}
 &\mathbb E^\mathbb Q\sup_{s\le\theta}\int_{B_R}|f_s^N(x)-f_s(x)|^2\,\mathrm d x\\
 &\quad\le \mathbb E^\mathbb Q\int_{B_K}\mathcal B_N(y)J^*(y)\,\mathrm d y\\
 &\qquad+\int_{|y|>K}\mathbb E^\mathbb Q\sup_{s\le\theta}
 |F_s^{N,0,y}-F_s^{0,y}|^2J_s(y)
 \mathbf 1_{\{|\Phi_s(y)|\le R\}}\,\mathrm d y.
\end{align*}
By $|F^N|\vee|F|\le\|\gamma\|_\infty$ and Lemma 
\ref{lem:weighted-multiplier}, the last term is bounded by
$C_R\int_{|y|>K}\left\langle y\right\rangle^{-a}\,\mathrm d y$.  For any $a>d$, taking  $N\to\infty$ and
$K\to\infty$, proves \eqref{eq:local-f-strong}.

For fixed $s$ and integer $R$, \eqref{eq:local-f-strong} yields
\[
 f_{s\wedge\theta}^N\longrightarrow f_{s\wedge\theta}
 \quad\text{in }L^2(\Omega;L^2(B_R)).
\]
The $\mathcal G_s^k$-measurable subspace of
$L^2(\Omega;L^2(B_R))$ is closed. Hence, Proposition \ref{prop:diagonal-Y} implies
that $f_{s\wedge\theta}$ is $\mathcal G_s^k$-measurable.

\label{def:localized-IW}
	Let $U$ be a scalar random field, let $A$ be scalar-valued, let $B$
	be $\mathbb R^m$-valued, and write $C=(C^1,\ldots,C^r)$. We say that
	$(U,A,B,C)$ satisfies condition $\mathrm{(IW)}_{n_*}$ on
	$[0,\theta]$ if, 
	\begin{equation}
		\mathrm{d}U_s
		=A_s\,\mathrm{d}s
		+B_s^\top\,\mathrm{d}Y_s
		+\sum_{\nu=1}^r C_s^\nu\,\mathrm{d}W_s^\nu.
		\label{eq:generic-parameter-semimartingale}
	\end{equation}
Here the identity holds as a semimartingale equality on $[0,\theta]$
after pairing with any $\varphi\in C_c^\infty(\mathbb R^d)$,
and $B,C$ admit predictable representatives.

	Moreover, for every $M<\infty$, there exist stopping times
	$\kappa_j^M\uparrow\theta$, $\mathbb Q$-a.s., such that, for every $j$,
	\begin{align}
		&\mathbb E^\mathbb Q\operatorname*{ess\,sup}_{s\le\kappa_j^M}
		\|U_s\|_{H^{n_*}(B_M)}^2
		+\mathbb E^\mathbb Q\int_0^{\kappa_j^M}
		\|A_s\|_{H^{n_*-2}(B_M)}\,\mathrm{d}s
		\notag\\
		&\qquad
		+\mathbb E^\mathbb Q\int_0^{\kappa_j^M}
		\left(
		\|B_s\|_{H^{n_*-1}(B_M)}^2
		+\|C_s\|_{H^{n_*-1}(B_M)}^2
		\right)\mathrm{d}s
		<\infty.
		\label{eq:IW-local-Sobolev-norms}
	\end{align}

\label{prop:truncated-IW}
For each $N$, the fields in \eqref{eq:reconstruct-N} satisfy
the following equation in the weak sense: 
\begin{equation}
 \,\mathrm d f_s^N(x)
 =-\left[L_sf_s^N(x)+h_N(x,u_s)^\top g_s^N(x)\right]\,\mathrm d s
  +(g_s^N(x))^\top\,\mathrm d Y_s,
 \quad f_\theta^N=\gamma.
 \label{eq:truncated-BSPDE}
\end{equation}

Moreover, let
$\{(F^{N,0,y},G^{N,0,y},\widetilde G^{N,0,y}):y\in\mathbb R^d\}$
be the solutions to \eqref{eq:truncated-BSDE} with $(t,x)=(0,y)$,
then the following holds
\begin{equation}
 \widetilde G_s^{N,0,y}
 =\sigma(\Phi_s(y),u_s)^\top
      \nabla f_s^N(\Phi_s(y))
 \in\mathbb R^r,\qquad
 \,\mathrm d\mathbb Q\otimes\,\mathrm d s\otimes\,\mathrm d y\text{-a.e.}
 \label{eq:tilde-identification-N}
\end{equation}
The fields $g^N$, $N\ge1$, and their limit $g$ from
Proposition~\ref{prop:local-eulerian} admit
$\mathbb F^Y$-predictable versions on $[0,\theta]$.

\label{prop:weak-passage}
The limit fields $(f,g)$ defined in \eqref{eq:reconstruct-limit}
satisfy the weak identity \eqref{eq:weak-bspde}.

\label{prop:weighted-Sobolev}
Let $(f,g)$ be the fields defined in
\eqref{eq:reconstruct-limit}. 
Set $\ell_0=d/2+2$.  Then
\begin{equation}
 \mathbb E^\mathbb Q\operatorname*{ess\,sup}_{s\le\theta}\left\lVert f_s\right\rVert_{H_{\ell_0}^{n_*}}^2
 +\mathbb E^\mathbb Q\int_0^\theta
    \left\lVert g_s\right\rVert_{H_{\ell_0}^{n_*}(\mathbb R^d;\mathbb R^m)}^2\,\mathrm d s
 <\infty.
 \label{eq:weighted-Sobolev-estimate}
\end{equation}

Using the change of variables $x=\Phi_s(y)$, with
$\mathrm{d}x=J_s(y)\,\mathrm{d}y$, and applying
\eqref{eq:chain-f}, we obtain
\begin{align*}
 &\int_{\mathbb R^d}|D^\alpha v_s^N(x)|^2
       \left\langle x\right\rangle^{-2\ell_0}\,\mathrm d x
 \le C_\alpha\sum_{|\beta|\le|\alpha|}
 \int_{\mathbb R^d}|D_y^\beta V_s^{N,0,y}|^2
 |P_{\alpha,\beta,s}(y)|^2\\
 &\hspace{9em}{}
 \times\left\langle \Phi_s(y)\right\rangle^{-2\ell_0}J_s(y)\,\mathrm d y.
\end{align*}
Applying H\"older's inequality, Proposition \ref{prop:uniform-parameter}, and Lemma 
\ref{lem:weighted-multiplier},   we obtain
\begin{align}
 &\sup_N\mathbb E^\mathbb Q\operatorname*{ess\,sup}_{s\le\theta}\left\lVert f_s^N\right\rVert_{H_{\ell_0}^{n_*}}^2
 +\sup_N\mathbb E^\mathbb Q\int_0^\theta
    \left\lVert g_s^N\right\rVert_{H_{\ell_0}^{n_*}}^2\,\mathrm d s\\
 &\qquad\le C_k\int_{\mathbb R^d}
   \left(\left\langle y\right\rangle^{-2\ell_0}+\left\langle y\right\rangle^{2-2\ell_0}\right)\,\mathrm d y<\infty. \label{eq:explicit-weight-integral}
\end{align}
After extending the processes by zero after $\theta$, the uniform
bounds yield a weakly convergent subsequence of $(f^N,g^N)$ in
\[
L^2\!\left(\Omega\times(0,T);
H_{\ell_0}^{n_*}(\mathbb R^d)\times
H_{\ell_0}^{n_*}(\mathbb R^d;\mathbb R^m)\right).
\]
The local strong convergence in Proposition~\ref{prop:local-eulerian}
identifies its weak limit with $(f,g)$. Applying
Lemma~\ref{lem:maximal-lsc} to the first component and weak lower
semicontinuity of the $L^2$ norm to the second component gives
\eqref{eq:weighted-Sobolev-estimate}.

\label{prop:weighted-pointwise}
With $\ell_0=d/2+2$, for every $\lambda\ge\ell_0$ and every
$|\alpha|\le2$, \eqref{eq:weighted-sup-2} holds.

Fix a multi-index $\alpha$ with $|\alpha|\le2$, and let
	$v\in H_{\ell_0}^{n_*}(\mathbb R^d)$.
	For $z\in\mathbb Z^d$, define $Q_z=z+(-1,1)^d$.
	Since $n_*-|\alpha|>d/2$, the Sobolev embedding
	\citep[Theorem~4.12, Part~I, Case~A, p.~85]{AdamsFournier2003}
	gives
	\begin{equation}
		\sup_{x\in Q_z}|D^\alpha v(x)|^2
		\le C\sum_{|\beta|\le n_*}
		\int_{Q_z}|D^\beta v(x)|^2\,\mathrm{d}x,
		\label{eq:local-Sobolev}
	\end{equation}
	where we use the continuous representative of $D^\alpha v$.
	By translation, the constant $C$ is independent of $z$.

	There exists a constant $c\ge1$, independent of $z$, such that
	\[
	c^{-1}\left\langle z\right\rangle\le\left\langle x\right\rangle\le c\left\langle z\right\rangle,
	\qquad x\in Q_z.
	\]
	Since the cubes $(Q_z)_{z\in\mathbb Z^d}$ cover $\mathbb R^d$,
	\eqref{eq:local-Sobolev} implies
	\begin{align*}
		\sup_{x\in\mathbb R^d}
		\frac{|D^\alpha v(x)|^2}{\left\langle x\right\rangle^{2\ell_0}}
		&\le C\sup_{z\in\mathbb Z^d}\left\langle z\right\rangle^{-2\ell_0}
		\sum_{|\beta|\le n_*}
		\int_{Q_z}|D^\beta v(x)|^2\,\mathrm{d}x\\
		&\le C\sup_{z\in\mathbb Z^d}
		\sum_{|\beta|\le n_*}
		\int_{Q_z}
		|D^\beta v(x)|^2\left\langle x\right\rangle^{-2\ell_0}\,\mathrm{d}x\\
		&\le C\left\lVert v\right\rVert_{H_{\ell_0}^{n_*}}^2.
	\end{align*}
	The same estimate holds for $\mathbb R^m$-valued functions by applying
	the scalar estimate to each component and summing.

	Applying this estimate to $v=f_s(\omega,\cdot)$ and
	$v=g_s(\omega,\cdot)$, taking the essential supremum in time
	for $f$ and integrating in time for $g$, and then taking
	expectations, Proposition~\ref{prop:weighted-Sobolev} yields
	\eqref{eq:weighted-sup-2} for $\lambda=\ell_0$.
	Finally, for $\lambda\ge\ell_0$,
	$\left\langle x\right\rangle^{-2\lambda}\le\left\langle x\right\rangle^{-2\ell_0}$, which proves the
	remaining cases.

\label{prop:local-time-continuity}
	Let $(f,g)$ be a weighted Sobolev solution of
	\eqref{eq:intro-dual-bspde}.
	Then $f$ admits a version such that, $\mathbb Q$-almost surely,
	for every $R<\infty$,
	\begin{equation}
		f\in C\bigl([0,\theta];H^{n_*-2}(B_R)\bigr)
		\hookrightarrow C\bigl([0,\theta];C(\overline B_R)\bigr),
		\label{eq:local-time-continuity}
	\end{equation}

Fix $R<\infty$. By the coefficient assumptions and Leibniz's rule,
	\begin{align*}
		\|L_sf_s\|_{H^{n_*-2}(B_R)}
		&\le C_R(1+|u_s|^2)\|f_s\|_{H^{n_*}(B_{R})},\\
		\|h(\cdot,u_s)^\top g_s\|_{H^{n_*-2}(B_R)}
		&\le C_R(1+|u_s|)\|g_s\|_{H^{n_*-2}(B_{R})}.
	\end{align*}
	Together with \eqref{eq:solution-norm}, Cauchy--Schwarz, and
	$\int_0^\theta |u_s|^2\,\mathrm d s\le k$, these estimates imply
	\begin{equation}\label{xp}
	\int_0^\theta
	\left(
	\|L_sf_s\|_{H^{n_*-2}(B_R)}
	+\|h(\cdot,u_s)^\top g_s\|_{H^{n_*-2}(B_R)}
	\right)\,\mathrm d s<\infty
	\qquad\mathbb Q\text{-a.s.}
	\end{equation}
	Moreover, \eqref{eq:solution-norm} gives
	\begin{equation}\label{xp1}
	\mathbb E^\mathbb Q\int_0^\theta
	\|g_s\|_{H^{n_*-2}(B_R;\mathbb R^m)}^2\,\mathrm d s<\infty.
	\end{equation}
By \eqref{xp} and \eqref{xp1},	the drift integral has continuous paths in $H^{n_*-2}(B_R)$,
	so does the Hilbert-valued stochastic integral
	\citep[Chapter~4]{DaPratoZabczyk2014}.
	Hence, the weak identity defines
	an $H^{n_*-2}(B_R)$-continuous modification of $f$.


Choose the modifications consistently for $R\in\mathbb N$, agreement
almost everywhere and time continuity imply indistinguishability on
overlaps. Finally,
$n_*-2>d/2$ and the Sobolev embedding give
\eqref{eq:local-time-continuity}.

\label{prop:f-bound}
Let $f$ be the continuous version chosen in
Proposition~\ref{prop:local-time-continuity}. There is an event $\Omega_0$ with
$\mathbb Q(\Omega_0)=1$ such that
\begin{equation}
 |f_s(\omega,x)|\le\|\gamma\|_\infty
 \quad\text{for every }\omega\in\Omega_0,
 \ 0\le s\le\theta(\omega),\ x\in\mathbb R^d.
 \label{eq:f-bound-common-version}
\end{equation}

Let $\bar f=f^1-f^2$ and $\bar g=g^1-g^2$, where $f^1$ and $f^2$
are taken to be the locally space--time continuous versions provided
by Proposition~\ref{prop:local-time-continuity}.



Fix  $t\in[0,T]$. On $A_t$, for
$t\le s\le\theta$,  define, 
	\begin{equation}
		\begin{aligned}
			\bar F_s^x&:=\bar f_s(X_s^{t,x}),\qquad
			\bar G_s^x:=\bar g_s(X_s^{t,x}),\\
			\overline{\widetilde G}_s^x
			&:=\sigma(X_s^{t,x},u_s)^\top
			\nabla\bar f_s(X_s^{t,x}).
		\end{aligned}
		\label{eq:uniqueness-characteristic-fields}
	\end{equation}
	By the forward formula \eqref{eq:forward-flow-IW} in
	Lemma~\ref{lem:flow-composition}, for Lebesgue-a.e.\ $x$,
	these processes satisfy, 
	\begin{equation}
		\,\mathrm d\bar F_s^x
		=-(H_s^{t,x})^\top\bar G_s^x\,\mathrm d s
		+(\bar G_s^x)^\top\,\mathrm d Y_s
		+(\overline{\widetilde G}_s^x)^\top\,\mathrm d W_s,
		\qquad \bar F_\theta^x=0.
		\label{eq:zero-terminal-flow-BSDE}
	\end{equation}
Applying 
Proposition~\ref{prop:density-stability}, we have
	\begin{equation}
		\begin{aligned}
			&\mathbf 1_{A_t}\bar F_s^x=0
			\quad(t\le s\le\theta),\qquad \mathbb Q\text{-a.s.},\\
			&\mathbf 1_{A_t}\bar G^x=0,\qquad
			\mathbf 1_{A_t}\overline{\widetilde G}^{x}=0,
			\quad \,\mathrm d\mathbb Q\otimes\,\mathrm d s\text{-a.e.},
		\end{aligned}
		\label{eq:characteristic-zero}
	\end{equation}
	for Lebesgue-a.e. $x$.

	Since $X_t^{t,x}=x$ on $A_t$ and
	$\bar f_{t\wedge\theta}=\bar f_\theta=0$ on $A_t^c$, we have 
	\begin{equation}
		\mathbb E^\mathbb Q\int_{B_R}|\bar f_{t\wedge\theta}(x)|^2\,\mathrm d x=0.
		\label{eq:integrated-f-zero}
	\end{equation}
Since there are only countably many rational $t\in[0,T]$ and
integer $R\ge1$, we may choose a single event of probability one
on which $\bar f_{t\wedge\theta}(x)=0$ for Lebesgue-a.e.\ $x\in B_R$
for all such $t$ and $R$.
Local space--time continuity then yields $\bar f=0$ everywhere
on $[0,\theta]\times\mathbb R^d$ on this event.

Taking $t=0$, we have $\bar G_s^x=\bar g_s(\Phi_s(x))=0$
for $\,\mathrm d\mathbb Q\otimes\,\mathrm d s$-a.e.\ $(\omega,s)$ with $s\le\theta$,
for Lebesgue-a.e.\ $x$.
Integrating $|\bar G_s^x|^2$ and by the change of variables $y=\Phi_s(x)$, gives
\begin{equation}
	\mathbb E^\mathbb Q\int_0^\theta\int_{\mathbb R^d}
	|\bar g_s(y)|^2J_s(\Psi_s(y))^{-1}\,\mathrm d y\,\mathrm d s=0.
	\label{eq:integrated-g-eulerian}
\end{equation}
Since the Jacobian factor is finite and strictly positive, we obtain 
$\bar g=0$ for $\,\mathrm d\mathbb Q\otimes\,\mathrm d s\otimes\,\mathrm d x$-a.e.\
$(\omega,s,x)$ with $0\le s\le\theta$. So we finish the proof.
